def transform(grid):
    # The four 4x4 panels are separated by color-3 divider columns.
    starts = [i + 1 for i, value in enumerate(grid[0]) if value == 3]
    panels = [ [row[start:start + 4] for row in grid] for start in starts ]
    if len(panels) != 4 or any(any(len(row) != 4 for row in panel) for panel in panels):
        raise ValueError('expected four 4x4 panels')
    out = []
    for r in range(4):
        row = []
        for c in range(4):
            values = [panel[r][c] for panel in panels]
            nonzero = [v for v in values if v != 0]
            if not nonzero:
                row.append(0)
            else:
                counts = Counter(nonzero)
                row.append(max(counts, key=lambda v: (counts[v], -values.index(v))))
        out.append(row)
    return out
